import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { useTheme } from "../context/ThemeContext";

const Navbar = () => {
  const navigate = useNavigate();
  const { toggleTheme } = useTheme();

  const token = localStorage.getItem("authToken");
  const user = JSON.parse(localStorage.getItem("user"));

  const isAuth = !!token;

  const handleLogout = () => {
    localStorage.removeItem("authToken");
    localStorage.removeItem("user");
    navigate("/");
    window.location.reload();
  };

  return (
    <nav
      style={{
        height: "70px",
        background: "#020f24",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "0 32px",
        borderBottom: "1px solid rgba(255,255,255,0.08)",
      }}
    >
      {/* LEFT */}
      <Link
        to="/"
        style={{
          fontWeight: 700,
          letterSpacing: "1px",
          color: "#fbbf24",
          textDecoration: "none",
          fontSize: "18px",
        }}
      >
        THESIS CHECK
      </Link>

      {/* CENTER */}
      <div style={{ display: "flex", gap: "20px" }}>
        <Link to="/" style={linkStyle}>Home</Link>
        <Link to="/about" style={linkStyle}>About</Link>
        <Link to="/contact" style={linkStyle}>Contact</Link>

        {isAuth && (
          <Link to="/dashboard" style={linkStyle}>
            Dashboard
          </Link>
        )}

        {isAuth && user?.role === "student" && (
          <Link to="/upload" style={uploadBtn}>
            Upload Thesis
          </Link>
        )}

        {isAuth && user?.role === "admin" && (
          <Link to="/admin" style={linkStyle}>
            Admin
          </Link>
        )}
      </div>

      {/* RIGHT */}
      <div style={{ display: "flex", alignItems: "center", gap: "14px" }}>
        <button onClick={toggleTheme} style={themeBtn}>
          🌙 / ☀️
        </button>

        {isAuth && user ? (
          <>
            {/* USER BADGE */}
            <div style={userBadge}>
              <span style={{ fontSize: "13px" }}>{user.email}</span>
              <span style={roleBadge(user.role)}>
                {user.role}
              </span>
            </div>

            <button onClick={handleLogout} style={logoutBtn}>
              Logout
            </button>
          </>
        ) : (
          <Link to="/login" style={loginBtn}>
            Log in
          </Link>
        )}
      </div>
    </nav>
  );
};

/* ---------------- STYLES ---------------- */

const linkStyle = {
  color: "#e5e7eb",
  textDecoration: "none",
  fontSize: "14px",
};

const uploadBtn = {
  background: "#fbbf24",
  color: "#111",
  padding: "6px 14px",
  borderRadius: "999px",
  fontWeight: 600,
  textDecoration: "none",
  fontSize: "13px",
};

const loginBtn = {
  border: "1px solid #fbbf24",
  color: "#fbbf24",
  padding: "6px 14px",
  borderRadius: "999px",
  textDecoration: "none",
  fontSize: "13px",
};

const logoutBtn = {
  background: "transparent",
  border: "1px solid #ef4444",
  color: "#ef4444",
  padding: "6px 14px",
  borderRadius: "999px",
  cursor: "pointer",
};

const themeBtn = {
  background: "transparent",
  border: "1px solid rgba(255,255,255,0.2)",
  color: "#fff",
  padding: "6px 10px",
  borderRadius: "999px",
  cursor: "pointer",
};

const userBadge = {
  display: "flex",
  flexDirection: "column",
  alignItems: "flex-end",
  fontSize: "12px",
};

const roleBadge = (role) => ({
  marginTop: "2px",
  padding: "2px 8px",
  borderRadius: "999px",
  fontSize: "11px",
  background:
    role === "admin"
      ? "#ef4444"
      : role === "advisor"
      ? "#3b82f6"
      : "#22c55e",
  color: "#000",
  fontWeight: 600,
});

export default Navbar;
